// Helper SVG Data URI generator for crisp self-contained design templates
const createSvgDataUrl = (svgContent: string): string => {
  let content = svgContent.trim();
  if (!content.includes('width=')) {
    content = content.replace('<svg', '<svg width="300" height="300"');
  }
  if (!content.includes('xmlns=')) {
    content = content.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
  }
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(content)}`;
};

